// Check photographs live in a private attachment endpoint, never in agreement JSON.
async function checkPhotoData(file){
 if(!file.type.startsWith('image/'))throw new Error('Select a photo of the front of the check');
 const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas');
 const factor=Math.min(1,1250/Math.max(bitmap.width,bitmap.height));
 canvas.width=Math.round(bitmap.width*factor);canvas.height=Math.round(bitmap.height*factor);
 const g=canvas.getContext('2d');g.fillStyle='#fff';g.fillRect(0,0,canvas.width,canvas.height);g.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close?.();
 let data=canvas.toDataURL('image/jpeg',0.72);
 if(data.length>1100000)data=canvas.toDataURL('image/jpeg',0.48);
 if(data.length>1100000)throw new Error('Image is too large. Retake the picture closer to the check.');
 return data;
}
function paymentRow(x={date:today(),method:'Cash',amount:0,reference:''},index=-1){
 const el=document.createElement('div');el.className='sa-line sa-payment';el.style.cssText='display:flex;flex-wrap:wrap;align-items:end';
 el.innerHTML=`<label style="flex:1 1 125px">Date<input data-pay="date" type="date" value="${html(x.date)}" required></label><label style="flex:1 1 130px">Method<select data-pay="method">${['Cash','Check','Card — paid externally','Bank funding received','Other'].map(m=>`<option ${m===x.method?'selected':''}>${m}</option>`).join('')}</select></label><label style="flex:1 1 115px">Amount ($)<input data-pay="amount" type="number" min="0.01" step="0.01" value="${x.amount/100}" required></label><label style="flex:1 1 155px"><span data-pay-label>Reference / receipt #</span><input data-pay="reference" value="${html(x.reference)}" placeholder="Receipt / check #"></label><button type="button" class="btn danger" aria-label="Remove payment record">×</button><div data-check style="display:none;width:100%;border:1px solid #dbe4ea;border-radius:10px;padding:12px;margin-top:8px"><b>Check photo — internal record only</b><p class="small">Photograph the front of the check using the camera or upload a picture. This is not proof the check has cleared and will not be included in customer copies.</p><label>Take photo / Upload check<input data-check-file type="file" accept="image/*" capture="environment"></label><img data-check-preview alt="Check attachment preview" hidden style="max-width:100%;max-height:240px;object-fit:contain;border:1px solid #dbe4ea;border-radius:8px;margin-top:8px"><div class="sa-controls"><button type="button" class="btn secondary" data-check-remove>Remove / replace image</button><span class="small" data-check-status>Check image required before saving.</span></div></div>`;
 const method=el.querySelector('[data-pay="method"]'),panel=el.querySelector('[data-check]'),photo=el.querySelector('[data-check-file]'),preview=el.querySelector('[data-check-preview]'),status=el.querySelector('[data-check-status]');
 function mode(){const check=method.value==='Check';panel.style.display=check?'block':'none';el.querySelector('[data-pay-label]').textContent=check?'Check number / reference':'Reference / receipt #';if(check&&!el.checkPhoto&&!el.checkPhotoSaved)status.textContent='Check image required before saving.'}
 method.addEventListener('change',()=>{mode();changed()});
 photo.onchange=async()=>{if(!photo.files?.[0])return;try{status.textContent='Preparing photo…';el.checkPhoto=await checkPhotoData(photo.files[0]);el.checkPhotoSaved=false;preview.src=el.checkPhoto;preview.hidden=false;status.textContent='Photo ready; save agreement to store securely.';changed()}catch(err){status.textContent=err.message;el.checkPhoto=null;photo.value=''}};
 el.querySelector('[data-check-remove]').onclick=()=>{el.checkPhoto=null;el.checkPhotoSaved=false;el.checkPhotoRemoved=true;preview.removeAttribute('src');preview.hidden=true;photo.value='';status.textContent='Image removed from this draft; retake before saving.';changed()};
 el.querySelector('button[aria-label="Remove payment record"]').onclick=()=>{el.remove();changed()};
 Q('#saPayments').append(el);mode();
 if(record?.id&&index>=0&&x.method==='Check'){
  const id=record.id;fetch(API+'/crm/v1/sales-drafts/'+id+'/check-images/'+index,{headers:{Authorization:'Bearer '+token},cache:'no-store'}).then(async r=>{if(!r.ok)throw Error('Not attached or not accessible');const blob=await r.blob();if(record?.id!==id||!el.isConnected)return;el.checkPhotoSaved=true;el.checkPhotoFingerprint=[x.date,x.method,x.amount,x.reference].join('|');const reader=new FileReader();reader.onload=()=>{if(el.isConnected){preview.src=reader.result;preview.hidden=false}};reader.readAsDataURL(blob);status.textContent='Private check image saved.'}).catch(()=>{if(el.isConnected)status.textContent='No saved image found. Take a photo to attach one.'});
 }
 return el;
}
function checkPaymentPhotosRequired(){
 for(const [i,el] of Array.from(Q('#saPayments').children).entries()){
  if(el.querySelector('[data-pay="method"]').value!=='Check')continue;
  const date=el.querySelector('[data-pay="date"]').value,amount=cents(el.querySelector('[data-pay="amount"]').value),ref=el.querySelector('[data-pay="reference"]').value.trim();
  if(!ref){Q('#saMessage').textContent='Enter the check number / reference for check payment '+(i+1);return false}
  const matches=el.checkPhotoSaved&&el.checkPhotoFingerprint===[date,'Check',amount,ref].join('|');
  if(!el.checkPhoto&&!matches){Q('#saMessage').textContent='Take a photo of the check for payment '+(i+1)+' before saving.';return false}
 }
 return true;
}
async function uploadCheckPhotos(saved){
 const rows=Array.from(Q('#saPayments').children);
 for(let index=0;index<rows.length;index++){
  const el=rows[index],method=el.querySelector('[data-pay="method"]').value;
  if(method!=='Check'||!el.checkPhoto)continue;
  await api('/crm/v1/sales-drafts/'+saved.id+'/check-images/'+index,{method:'POST',body:JSON.stringify({image:el.checkPhoto})});
 }
}
// Approved pricing is keyed by exact factory model number. No invented wholesale values.
let quoteRequest=0;
async function applyModelPrice(){
 const brand=Q('#saBrand').value,model=Q('#saModel').value.trim(),request=++quoteRequest;
 if(!brand||!model)return;
 Q('#saPricingNotice').textContent='Checking approved model price…';
 try{
  const p=await api('/crm/v1/sales-pricebook/quote?brand='+encodeURIComponent(brand)+'&model='+encodeURIComponent(model));
  if(request!==quoteRequest)return;
  Q('#saMsrp').value=(p.list_price_cents/100).toFixed(2);
  synchronizeDiscount();changed();
  Q('#saPricingNotice').textContent='Price loaded from protected model pricebook. Optional sale price may be entered below.';
 }catch(e){
  if(request!==quoteRequest)return;
  Q('#saPricingNotice').textContent='No approved model price found. Administrator must import or approve this model before quoting.';
 }
}
function synchronizeDiscount(){
 const msrp=cents(Q('#saMsrp').value);
 const raw=Q('#saSalePrice').value.trim();
 const sale=raw===''?msrp:cents(raw);
 Q('#saDiscount').value=String(Math.max(0,msrp-sale)/100);
 Q('#saSalePrice').setCustomValidity(raw!==''&&sale>msrp?'Sale price cannot exceed MSRP':'');
}
Q('#saSalePrice').addEventListener('input',()=>{synchronizeDiscount();changed()});
Q('#saMsrp').addEventListener('input',synchronizeDiscount);
function data(){synchronizeDiscount();const customer={};dialog.querySelectorAll('[data-customer]').forEach(e=>customer[e.dataset.customer]=e.value.trim());return{customer,submission_id:record?.document?.submission_id||'',contract_date:Q('#saDate').value,salesperson:Q('#saSalesperson').value,location:Q('#saLocation').value,spa:{brand:Q('#saBrand').value,model:Q('#saModel').value,year:record?.document?.spa?.year||'',serial:Q('#saSerial').value,shell:Q('#saShell').value==='__custom'?Q('#saShellCustom').value.trim():Q('#saShell').value,cabinet:Q('#saCabinet').value==='__custom'?Q('#saCabinetCustom').value.trim():Q('#saCabinet').value,manufacturer_add_ons:Q('#saManufacturerAddOns').value},msrp:cents(Q('#saMsrp').value),discount:cents(Q('#saDiscount').value),tax_rate:cents(Q('#saTaxRate').value),items:Array.from(Q('#saItems').children,e=>({description:e.querySelector('[data-item="description"]').value,quantity:Number(e.querySelector('[data-item="quantity"]').value),unit_price:cents(e.querySelector('[data-item="price"]').value),taxable:e.querySelector('[data-item="taxable"]').checked})),payments:Array.from(Q('#saPayments').children,e=>({date:e.querySelector('[data-pay="date"]').value,method:e.querySelector('[data-pay="method"]').value,amount:cents(e.querySelector('[data-pay="amount"]').value),reference:e.querySelector('[data-pay="reference"]').value})),finance:{bank:Q('#saBank').value.trim(),amount:cents(Q('#saFinanced').value),complete:Q('#saFinanceComplete').checked},notes:Q('#saNotes').value}}
function totals(d){const net=d.msrp-d.discount,subtotal=net+d.items.reduce((s,x)=>s+x.unit_price*x.quantity,0),tax=Math.round((net+d.items.filter(x=>x.taxable).reduce((s,x)=>s+x.unit_price*x.quantity,0))*d.tax_rate/10000),total=subtotal+tax,paid=d.payments.reduce((s,x)=>s+x.amount,0),funded=d.payments.filter(x=>x.method==='Bank funding received').reduce((s,x)=>s+x.amount,0),outstanding=Math.max(0,d.finance.amount-funded),balance=Math.max(0,total-paid);return{subtotal,tax,total,paid,balance,overpayment:Math.max(0,paid-total),outstanding,eligible:total>0&&(paid>=total||(d.finance.complete&&d.finance.bank&&outstanding>=balance))}}
function update(){const d=data(),t=totals(d);Q('#saMsrp').setCustomValidity(d.discount>d.msrp?'Discount exceeds MSRP':'');Q('#saDiscount').setCustomValidity(d.discount>d.msrp?'Discount cannot exceed MSRP':'');Q('#saTotals').innerHTML=[['Spa MSRP',d.msrp],...(d.discount>0?[['Sale discount',-d.discount],['Discounted spa sale price',d.msrp-d.discount]]:[]),['Subtotal',t.subtotal],['Sales tax',t.tax],['Total price',t.total],['Payments recorded',t.paid],['Balance due',t.balance],['Unfunded financing',t.outstanding],...(t.overpayment?[['Overpayment / credit',t.overpayment]]:[])].map(([k,v])=>`<dt>${k}</dt><dd>${money(v)}</dd>`).join('');Q('#saEligibility').textContent=t.eligible?'Payment prerequisite met based on these entries. This is still a draft; delivery scheduling is not enabled.':'Payment prerequisite not met: full payment or completed financing covering the remaining balance is required before scheduling.';}
